17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Locale;
23	import java.util.Objects;
24	
25	import org.springframework.http.HttpHeaders;
26	import org.springframework.http.HttpStatus;
27	import org.springframework.http.ResponseEntity;
28	import org.springframework.samples.petclinic.mapper.OwnerMapper;
29	import org.springframework.samples.petclinic.mapper.PetMapper;
30	import org.springframework.samples.petclinic.mapper.VisitMapper;
31	import org.springframework.samples.petclinic.model.Owner;
32	import org.springframework.samples.petclinic.model.Pet;
33	import org.springframework.samples.petclinic.model.Visit;
34	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerException;
35	import org.springframework.samples.petclinic.rest.api.OwnersApi;
36	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
37	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.PetDto;
39	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
42	import org.springframework.samples.petclinic.service.ClinicService;
43	import org.springframework.security.access.prepost.PreAuthorize;
44	import org.springframework.web.bind.annotation.CrossOrigin;
45	import org.springframework.web.bind.annotation.RequestMapping;
46	import org.springframework.web.bind.annotation.RestController;
47	import org.springframework.web.util.UriComponentsBuilder;
48	
49	import jakarta.transaction.Transactional;
50	
51	/**
52	 * @author Vitaliy Fedoriv
53	 */
54	
55	@RestController
56	@CrossOrigin(exposedHeaders = "errors, content-type")
57	@RequestMapping("/api")
58	public class OwnerRestControllerV1 implements OwnersApi {
59	
60	    private final ClinicService clinicService;
61	
62	    private final OwnerMapper ownerMapper;
63	
64	    private final PetMapper petMapper;
65	
66	    private final VisitMapper visitMapper;
67	
68	    public OwnerRestControllerV1(ClinicService clinicService,
69	                                 OwnerMapper ownerMapper,
70	                                 PetMapper petMapper,
71	                                 VisitMapper visitMapper) {
72	        this.clinicService = clinicService;
73	        this.ownerMapper = ownerMapper;
74	        this.petMapper = petMapper;
75	        this.visitMapper = visitMapper;
76	    }
77	
78	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
79	    @Override
80	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
81	        Collection<Owner> owners;
82	        if (lastName != null) {
83	            owners = this.clinicService.findOwnerByLastName(lastName);
84	        } else {
85	            owners = this.clinicService.findAllOwners();
86	        }
87	        if (owners.isEmpty()) {
88	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
89	        }
90	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
91	    }
92	
93	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
94	    @Override
95	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
96	        Owner owner = this.clinicService.findOwnerById(ownerId);
97	        if (owner == null) {
98	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
99	        }
100	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
106	        HttpHeaders headers = new HttpHeaders();
107	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
108	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
109	        if (owner.getRegistrationDate() == null) {
110	            owner.setRegistrationDate(LocalDate.now());
111	        }
112	        if (isDuplicateTelephone(owner)) {
113	            throw new DuplicateOwnerException("An owner with telephone "
114	                + owner.getTelephone() + " already exists");
115	        }
116	        if (isDuplicateEmail(owner)) {
117	            throw new DuplicateOwnerException("An owner with email "
118	                + owner.getEmail() + " already exists");
119	        }
120	        owner.setMembershipNumber(this.clinicService.findAllOwners().size() + 1);
121	        owner.setCity(resolveCity(owner.getCity()));
122	        owner.setCustomerCode(nextCustomerCode(owner.getCity()));
123	        this.clinicService.saveOwner(owner);
124	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
125	        headers.setLocation(UriComponentsBuilder.newInstance()
126	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
127	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
128	    }
129	
130	    /**
131	     * Determines whether any other owner already uses the candidate's telephone number.
132	     * The comparison ignores letter case and surrounding or repeated whitespace.
133	     *
134	     * @param candidate the owner about to be created
135	     * @return {@code true} if an owner with the same telephone is already present in the data store
136	     */
137	    private boolean isDuplicateTelephone(Owner candidate) {
138	        String telephone = normalizeTelephone(candidate.getTelephone());
139	        return this.clinicService.findAllOwners().stream()
140	            .anyMatch(existing -> Objects.equals(normalizeTelephone(existing.getTelephone()), telephone));
141	    }
142	
143	    /**
144	     * Canonicalises a telephone number by stripping every character that is not a digit
145	     * (for example spaces, dashes and parentheses), so that {@code "(613) 555-0100"} and
146	     * {@code "6135550100"} are treated as the same number. This is the form persisted for
147	     * an owner and used for the telephone-uniqueness check.
148	     *
149	     * @param telephone the raw telephone value, possibly {@code null}
150	     * @return the digits-only telephone, or {@code null} if {@code telephone} was {@code null}
151	     */
152	    private static String normalizeTelephone(String telephone) {
153	        if (telephone == null) {
154	            return null;
155	        }
156	        return telephone.replaceAll("[^0-9]", "");
157	    }
158	
159	    /**
160	     * Determines whether any other owner already uses the candidate's email address.
161	     * An absent or blank email is never considered a duplicate. The comparison ignores
162	     * letter case and surrounding or repeated whitespace.
163	     *
164	     * @param candidate the owner about to be created
165	     * @return {@code true} if an owner with the same email is already present in the data store
166	     */
167	    private boolean isDuplicateEmail(Owner candidate) {
168	        String email = normalize(candidate.getEmail());
169	        if (email == null || email.isBlank()) {
170	            return false;
171	        }
172	        return this.clinicService.findAllOwners().stream()
173	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
174	    }
175	
176	    /**
177	     * Builds the customer code for a newly created owner, formatted as
178	     * {@code '<UPPERCASE_CITY>-<NNNN>'} where {@code NNNN} is one more than the number of
179	     * owners already present in the same city, zero-padded to four digits
180	     * (e.g. {@code 'LONDON-0007'}). Cities are matched ignoring letter case.
181	     *
182	     * @param city the city of the owner about to be created
183	     * @return the formatted customer code
184	     */
185	    /**
186	     * Resolves the city name to store for a newly created owner. The supplied city is
187	     * normalised to title case (each word's first letter upper-cased, the rest lower-cased),
188	     * so that {@code "new york"} and {@code "NEW YORK"} both become {@code "New York"}.
189	     * However, if an owner already exists in that city (matched ignoring letter case), that
190	     * existing owner's exact spelling of the city is reused instead, so a single canonical
191	     * spelling is kept per city (for example an existing {@code "McFarland"} is preserved
192	     * rather than being flattened to {@code "Mcfarland"}).
193	     *
194	     * @param city the raw city supplied for the owner about to be created
195	     * @return the existing owner's spelling if the city is already known, otherwise the
196	     *         title-cased city; {@code null} if {@code city} was {@code null}
197	     */
198	    private String resolveCity(String city) {
199	        if (city == null) {
200	            return null;
201	        }
202	        return this.clinicService.findAllOwners().stream()
203	            .map(Owner::getCity)
204	            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
205	            .findFirst()
206	            .orElseGet(() -> titleCase(city));
207	    }
208	
209	    /**
210	     * Converts a city name to title case: each whitespace-separated word has its first letter
211	     * upper-cased and its remaining letters lower-cased, while the original whitespace is left
212	     * untouched. For example {@code "san   FRANCISCO"} becomes {@code "San   Francisco"}.
213	     *
214	     * @param city the city to title-case
215	     * @return the title-cased city
216	     */
217	    private static String titleCase(String city) {
218	        StringBuilder result = new StringBuilder(city.length());
219	        boolean startOfWord = true;
220	        for (int i = 0; i < city.length(); i++) {
221	            char c = city.charAt(i);
222	            if (Character.isWhitespace(c)) {
223	                startOfWord = true;
224	                result.append(c);
225	            } else if (startOfWord) {
226	                result.append(Character.toTitleCase(c));
227	                startOfWord = false;
228	            } else {
229	                result.append(Character.toLowerCase(c));
230	            }
231	        }
232	        return result.toString();
233	    }
234	
235	    private String nextCustomerCode(String city) {
236	        long ownersInCity = this.clinicService.findAllOwners().stream()
237	            .filter(existing -> existing.getCity() != null
238	                && existing.getCity().equalsIgnoreCase(city))
239	            .count();
240	        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), ownersInCity + 1);
241	    }
242	
243	    /**
244	     * Canonicalises a value for duplicate detection so that comparisons ignore letter
245	     * case and surrounding or repeated whitespace. Surrounding whitespace is stripped,
246	     * any run of internal whitespace is collapsed to a single space, and the result is
247	     * lower-cased. For example {@code "  john   smith "} and {@code "John Smith"} both
248	     * normalise to {@code "john smith"}.
249	     *
250	     * @param value the raw value, possibly {@code null}
251	     * @return the normalised value, or {@code null} if {@code value} was {@code null}
252	     */
253	    private static String normalize(String value) {
254	        if (value == null) {
255	            return null;
256	        }
257	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
258	    }
259	
260	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
261	    @Override
262	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
263	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
264	        if (currentOwner == null) {
265	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
266	        }
267	        currentOwner.setAddress(ownerFieldsDto.getAddress());
268	        currentOwner.setCity(ownerFieldsDto.getCity());
269	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
270	        currentOwner.setLastName(ownerFieldsDto.getLastName());
271	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
272	        this.clinicService.saveOwner(currentOwner);
273	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
274	    }
275	
276	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
277	    @Transactional
278	    @Override
279	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
280	        Owner owner = this.clinicService.findOwnerById(ownerId);
281	        if (owner == null) {
282	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
283	        }
284	        this.clinicService.deleteOwner(owner);
285	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
286	    }
287	
288	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
289	    @Override
290	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
291	        Owner owner = this.clinicService.findOwnerById(ownerId);
292	        if (owner == null) {
293	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
294	        }
295	        HttpHeaders headers = new HttpHeaders();
296	        Pet pet = petMapper.toPet(petFieldsDto);
297	        owner.setId(ownerId);
298	        pet.setOwner(owner);
299	        pet.getType().setName(null);
300	        this.clinicService.savePet(pet);
301	        PetDto petDto = petMapper.toPetDto(pet);
302	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
303	            .buildAndExpand(pet.getId()).toUri());
304	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
305	    }
306	
307	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
308	    @Override
309	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
310	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
311	        if (currentOwner != null) {
312	            Pet currentPet = this.clinicService.findPetById(petId);
313	            if (currentPet != null) {
314	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
315	                currentPet.setName(petFieldsDto.getName());
316	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
317	                this.clinicService.savePet(currentPet);
318	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
319	            }
320	        }
321	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
322	    }
323	
324	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
325	    @Override
326	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
327	        HttpHeaders headers = new HttpHeaders();
328	        Visit visit = visitMapper.toVisit(visitFieldsDto);
329	        Pet pet = new Pet();
330	        pet.setId(petId);
331	        visit.setPet(pet);
332	        this.clinicService.saveVisit(visit);
333	        VisitDto visitDto = visitMapper.toVisitDto(visit);
334	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
335	            .buildAndExpand(visit.getId()).toUri());
336	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
337	    }
338	
339	
340	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
341	    @Override
342	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
343	        Owner owner = this.clinicService.findOwnerById(ownerId);
344	        if (owner != null) {
345	            Pet pet = owner.getPet(petId);
346	            if (pet != null) {
347	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
348	            }
349	        }
350	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
351	    }
352	}
