        // No email supplied: the email uniqueness rule must not apply.
        String body = """
            {"firstName":"Jane","lastName":"Quinnelle","address":"999 Other St.","city":"Springfield","telephone":"6085551301"}
            """;
        mvc.perform(post("/api/owners").content(body)
